CREATE TABLE "public"."barbeiros" (
  "id"            bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nome"          text   NOT NULL,
  "telefone"      text   NOT NULL,
  "especialidade" text,
  CONSTRAINT "barbeiros_pkey" PRIMARY KEY (id),
  CONSTRAINT "ck_barb_telefone" CHECK ((telefone ~ '^[0-9]{10,11}$'::text))
);

ALTER TABLE "public"."barbeiros"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "catalogo_barbeiros_leitura" ON "public"."barbeiros"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

REVOKE ALL ON SEQUENCE "public"."barbeiros_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."barbeiros_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."barbeiros_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."barbeiros_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."barbeiros_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."barbeiros_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."barbeiros_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."barbeiros_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."barbeiros" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."barbeiros" TO "service_role";

REVOKE ALL ON TABLE "public"."barbeiros" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."barbeiros" TO "postgres";
